import {soundRegions,prepareSpeech,pronunciationAssessment,wavBytes,speechReport,validateExcerpt,resample} from './speech-core.js';
import {manualAssessment,DOMAINS} from './experience.js';
import {PocketTTS} from './vendor/pocket-tts/index.js';
const $=id=>document.getElementById(id);
const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const modelBase='https://huggingface.co/vlapky/pocket-tts-onnx/resolve/c469236dbc5f68287fa2fbf175b66de3b80123af/onnx';
export function createSpeechStudio({getState,getProfile,getDomain,onChange,onRender,toast,download,audio}){
 let generation=0,worker,pending,tts,ttsMode,voiceRef,voiceSource,ttsBusy=false,outputUrl,feedbackAudio,outputBlob,previous={},recordUrl;
 const status=t=>$('speechStatus').textContent=t;
 const voiceStatus=t=>$('voiceStatus').textContent=t;
 function stopFeedback(){generation++;window.speechSynthesis?.cancel();feedbackAudio?.pause();feedbackAudio=null;if(ttsBusy){tts?.destroy();tts=null;ttsMode=null;ttsBusy=false;}$('speak').textContent='▶ Listen to feedback';$('speak').disabled=!getState().result;$('downloadAudio').disabled=!getState().result;}
 function invalidate(){stopFeedback();if(outputUrl)URL.revokeObjectURL(outputUrl);outputUrl=null;outputBlob=null;$('downloadAudio').disabled=true;if(pending){worker?.terminate();worker=null;pending.reject(Error('Comparison cancelled because the practice changed.'));pending=null;}status('Choose the same word or short phrase in both recordings.');}
 function cancel(){invalidate();worker?.terminate();worker=null;tts?.destroy();tts=null;ttsMode=null;voiceRef=null;voiceSource=null;}
 function range(side){return [Number($(side+'Start').value),Number($(side+'End').value)];}
 function setRange(side,a,b){$(side+'Start').value=a.toFixed(2);$(side+'End').value=b.toFixed(2);}
 function context(){return {phrase:$('targetPhrase').value.trim(),language:getProfile().language,referenceRange:range('reference'),learnerRange:range('learner'),samePhrase:$('samePhrase').checked};}
 function sync(){const state=getState(),language=getDomain()==='language';$('speechSetup').classList.toggle('hidden',!language);$('soundEvidence').classList.toggle('hidden',!state.result?.phoneRows||!language);
 for(const side of ['reference','learner']){const item=state[side];$(side+'Excerpt').classList.toggle('hidden',!language||!item?.speechSamples);$(side+'Download').classList.toggle('hidden',!item?.recorded||!item.blob);
 if(previous[side]!==item){previous[side]=item;if(side==='reference'&&item?.speechSamples){$('voiceStart').value='0';$('voiceEnd').value=Math.min(8,item.duration).toFixed(1);$('voiceConsent').checked=false;}$('samePhrase').checked=false;if(item?.speechSamples){const regions=soundRegions(item.speechSamples,16000);item.soundRegions=regions;const r=regions[0]||{start:0,end:Math.min(item.duration,8)};setRange(side,r.start,Math.min(r.end,r.start+8));$(side+'Regions').innerHTML='<option value="">Choose a detected sound region…</option>'+regions.map((r,i)=>`<option value="${i}">${i+1}: ${r.start.toFixed(2)}–${r.end.toFixed(2)} seconds</option>`).join('');$(side+'RegionInfo').textContent=regions.length>1?`${regions.length} sound regions found. Choose ONE instance of the target, then listen to confirm.`:'Check the selected excerpt contains the target. Sound detection is not word recognition.';}}}
 if(state.result?.phoneRows){const r=state.result;$('speechSummary').textContent=r.summary;$('phoneRows').innerHTML=r.phoneRows.map(x=>`<tr><td>${safe(x.reference?.symbol||'—')}<small>${x.reference?x.reference.start.toFixed(2)+' s':''}</small></td><td>${safe(x.learner?.symbol||'—')}<small>${x.learner?x.learner.start.toFixed(2)+' s':''}</small></td><td>${safe(x.kind==='match'?'Matching sound':x.kind==='substitution'?'Different sound':x.kind==='missing'?'Not recognized in attempt':'Additional sound')}</td></tr>`).join('');$('referenceStrengths').innerHTML=r.referenceGuide.length?r.referenceGuide.map(x=>`<li>${safe(x.text)}</li>`).join(''):'<li>Not enough clear matching sounds to identify a strength reliably. Listen again before interpreting the differences.</li>';}
 $('downloadAudio').disabled=!state.result||ttsBusy;}
 function preview(side){const item=getState()[side];if(!item?.url){toast('Reattach the recording to play the original excerpt.');return;}const v=$(side+'Video'),[a,b]=range(side);if(a<0||b<=a||b>item.duration+.02){toast('Choose valid start and end times first.');return;}for(const s of ['reference','learner'])$(s+'Video').pause();v.currentTime=a;v.muted=false;v.playbackRate=.85;v.play().catch(()=>toast('Use the player to start playback.'));v.ontimeupdate=()=>{if(v.currentTime>=b){v.pause();v.ontimeupdate=null;}};}
 async function compare(){const state=getState(),c=context();if(!c.phrase)throw Error('Enter the word or phrase you are practicing, then select its spoken portion in both recordings.');if(!/^en(?:glish)?(?:[-\s(].*)?$/i.test(c.language))throw Error('Sound-level feedback is currently validated for English only. Choose English in your profile, or use manual observations for other languages.');if(!$('samePhrase').checked)throw Error('Listen to both excerpts, then confirm they contain the same word or short phrase.');
 const clips=['reference','learner'].map(side=>{const item=state[side];if(!item?.speechSamples)throw Error('Add a decodable audio/video recording on both sides. Saved reports need their recordings reattached.');return prepareSpeech(item.speechSamples,16000,range(side));});
 tts?.destroy();tts=null;ttsMode=null;const token=++generation;status('Starting sound analysis…');
 if(!worker)worker=new Worker(new URL('./phoneme-worker.js',import.meta.url),{type:'module'});
 const phones=await new Promise((resolve,reject)=>{const timer=setTimeout(()=>{worker?.terminate();worker=null;pending=null;reject(Error('Speech analysis took too long. Try a shorter excerpt on a desktop browser.'));},240000);const finish=(fn,value)=>{clearTimeout(timer);pending=null;fn(value);};pending={reject:e=>finish(reject,e)};worker.onmessage=({data})=>{if(data.type==='progress')status(data.message);else if(data.type==='result')finish(resolve,data.phones);else if(data.type==='error')finish(reject,Error(data.message));};worker.onerror=()=>{worker?.terminate();worker=null;finish(reject,Error('The speech model could not run on this device. Try a desktop browser with enough free memory.'));};worker.postMessage({clips},clips.map(x=>x.samples.buffer));});
 if(token!==generation)throw Error('The practice changed. Compare the current recordings again.');
 const r=pronunciationAssessment({phones:phones[0],range:range('reference'),hash:state.reference.hash},{phones:phones[1],range:range('learner'),hash:state.learner.hash},c);status('Sound comparison complete. Review possible differences by listening to the original moments.');return r;}
 function feedbackText(){const r=getState().result;if(!r)return '';if(r.phoneRows){const findings=r.findings.filter(x=>x.review!=='dismissed').slice(0,3);return `Generated MIMORA coaching. You are practicing ${r.context.phrase}. ${r.summary} ${r.referenceGuide.length?'Keep the sounds that match your reference. ':''}${findings.map(f=>`At ${f.learner?.[0]?.toFixed(1)||'the selected'} seconds, check a ${f.category.toLowerCase()}. ${f.action}`).join(' ')} Repeat the expert excerpt, then record one focused retry. These are possible differences, not a pronunciation grade.`;}return `Generated MIMORA coaching. ${r.findings.filter(x=>x.review!=='dismissed').slice(0,3).map(f=>f.observation+' '+f.action).join(' ')||'Replay the expert and your attempt. Choose one detail to refine, then record a focused retry.'}`;}
 async function neuralVoice(){const mode=$('feedbackVoice').value;const expert=getState().reference;if(mode==='expert'){if(!$('voiceConsent').checked)throw Error('Confirm that you have permission to reproduce this expert’s voice.');if(!expert?.speechSamples)throw Error('Add the expert recording to use their voice.');const a=Number($('voiceStart').value),b=Number($('voiceEnd').value);if(!Number.isFinite(a)||!Number.isFinite(b)||a<0||b>expert.duration+.01||b-a<3||b-a>10)throw Error('Select 3–10 seconds of clean speech from the expert for the voice sample.');}
 if(tts&&ttsMode!==mode){tts.destroy();tts=null;}if(!tts){tts=new PocketTTS({language:'english_2026-04',voiceCloning:mode==='expert',modelBaseUrl:modelBase,maxThreads:1,ortBaseUrl:'https://cdn.jsdelivr.net/npm/onnxruntime-web@1.24.3/dist/',cacheName:'mimora-pocket-v1'});ttsMode=mode;await tts.load(p=>{voiceStatus(p.type==='progress'?`Loading natural voice: ${p.label} ${p.total?Math.round(p.loaded/p.total*100)+'%':''}`:'Preparing natural voice…');});voiceRef=null;voiceSource=null;}
 if(mode==='expert'){const a=Number($('voiceStart').value),b=Number($('voiceEnd').value),key=expert.hash+':'+a+':'+b;if(voiceSource!==key){voiceStatus('Learning the permitted voice sample on this device…');voiceRef=await tts.cloneVoice(expert.speechSamples.slice(a*16000,b*16000),{inputSampleRate:16000,name:'permitted-expert'});voiceSource=key;}}else if(!voiceRef){const names=tts.predefinedVoices;voiceRef=await tts.loadVoice(names.includes('alba')?'alba':names[0]);}return voiceRef;}
 async function generate(){if(ttsBusy)throw Error('Voice generation is already running. Use Stop to cancel.');worker?.terminate();worker=null;const token=generation;ttsBusy=true;$('stopVoice').classList.remove('hidden');$('speak').disabled=true;$('downloadAudio').disabled=true;try{await neuralVoice();if(token!==generation)throw Error('Voice generation cancelled.');const chunks=[];voiceStatus('Generating natural coaching audio…');await tts.generate(feedbackText(),{voice:voiceRef,onChunk:chunk=>chunks.push(chunk.slice())});if(token!==generation)throw Error('Voice generation cancelled.');const samples=new Float32Array(chunks.reduce((n,x)=>n+x.length,0));let at=0;for(const chunk of chunks){samples.set(chunk,at);at+=chunk.length;}if(!samples.length||samples.some(x=>!Number.isFinite(x)))throw Error('Voice generation returned no usable audio.');outputBlob=new Blob([wavBytes(samples,tts.sampleRate)],{type:'audio/wav'});if(outputUrl)URL.revokeObjectURL(outputUrl);outputUrl=URL.createObjectURL(outputBlob);voiceStatus($('feedbackVoice').value==='expert'?'Generated coaching in the permitted expert voice. This is synthetic speech, not an original expert statement.':'Generated coaching in a natural preset voice.');return outputBlob;}catch(e){tts?.destroy();tts=null;ttsMode=null;throw e;}finally{ttsBusy=false;$('speak').disabled=!getState().result;$('downloadAudio').disabled=!getState().result;$('stopVoice').classList.add('hidden');}}
 async function speak(fallback){if(feedbackAudio&&!feedbackAudio.paused){stopFeedback();return;}const mode=$('feedbackVoice').value;if(mode==='device'){const utterance=new SpeechSynthesisUtterance(fallback||feedbackText());const voices=speechSynthesis.getVoices();utterance.voice=voices.find(v=>v.voiceURI===$('deviceVoice').value)||voices.find(v=>/en/i.test(v.lang)&&/natural|premium|enhanced|google|samantha|daniel/i.test(v.name))||voices.find(v=>v.lang.startsWith('en'));utterance.rate=.95;speechSynthesis.cancel();speechSynthesis.speak(utterance);voiceStatus('Using your selected device voice. Quality depends on installed voices.');return;}try{await audio().resume();if(!outputBlob)await generate();feedbackAudio=new Audio(outputUrl);await feedbackAudio.play();$('speak').textContent='■ Stop feedback';feedbackAudio.onended=()=>$('speak').textContent='▶ Listen to feedback';}catch(e){toast(e.message);voiceStatus(e.message);}}
 async function downloadFeedback(){try{if($('feedbackVoice').value==='device'){toast('Choose Natural coach or Expert voice to download generated audio.');return;}const blob=outputBlob||await generate();download(await blob.arrayBuffer(),$('feedbackVoice').value==='expert'?'mimora-generated-expert-voice.wav':'mimora-generated-coaching.wav','audio/wav');}catch(e){toast(e.message);voiceStatus(e.message);}}
 $('manualSpeechReview').onclick=()=>{const s=getState();if(!s.reference||!s.learner){toast('Add both recordings first.');return;}invalidate();s.result=manualAssessment({...DOMAINS.language,domain:"language"},s.reference,s.learner);s.result.domain='language';s.result.profile=structuredClone(getProfile());s.result.context=context();onRender();status('Manual review: add your own timestamped observations. Sound-level corrections have not been generated.');};
 for(const side of ['reference','learner']){
 $(side+'Preview').onclick=()=>preview(side);$(side+'Regions').onchange=e=>{const r=getState()[side]?.soundRegions?.[e.target.value];if(r){setRange(side,r.start,Math.min(r.end,r.start+8));$('samePhrase').checked=false;onChange();}};
 for(const suffix of ['Start','End'])$(side+suffix).onchange=()=>{$('samePhrase').checked=false;onChange();};
 $(side+'Download').onclick=async()=>{const m=getState()[side];if(!m?.blob)return;const ext=m.blob.type.includes('mp4')?'mp4':m.blob.type.includes('ogg')?'ogg':'webm';download(await m.blob.arrayBuffer(),`mimora-${side}-recording.${ext}`,m.blob.type||'application/octet-stream');};
 }
 $('targetPhrase').oninput=()=>onChange();$('samePhrase').onchange=()=>onChange();
 $('feedbackVoice').onchange=()=>{stopFeedback();outputBlob=null;if(outputUrl)URL.revokeObjectURL(outputUrl);outputUrl=null;$('expertVoiceOptions').classList.toggle('hidden',$('feedbackVoice').value!=='expert');$('deviceVoice').classList.toggle('hidden',$('feedbackVoice').value!=='device');voiceStatus('');};
 for(const id of ['voiceStart','voiceEnd','voiceConsent'])$(id).onchange=()=>{stopFeedback();outputBlob=null;if(outputUrl)URL.revokeObjectURL(outputUrl);outputUrl=null;};
 $('stopVoice').onclick=()=>{stopFeedback();$('stopVoice').classList.add('hidden');$('speak').disabled=!getState().result;voiceStatus('Voice generation stopped.');};
 function voices(){const list=window.speechSynthesis?.getVoices()||[];$('deviceVoice').innerHTML=list.map(v=>`<option value="${safe(v.voiceURI)}">${safe(v.name)} · ${safe(v.lang)}</option>`).join('');const natural=list.find(v=>/^en/.test(v.lang)&&/natural|premium|enhanced|google|samantha|daniel/i.test(v.name));if(natural)$('deviceVoice').value=natural.voiceURI;}
 if(window.speechSynthesis){speechSynthesis.addEventListener('voiceschanged',voices);voices();}
 return {sync,compare,invalidate,cancel,stopFeedback,speak,downloadFeedback,context,report:r=>speechReport(r,$('sessionTitle').value),restore:c=>{if(c?.referenceRange)setRange('reference',...c.referenceRange);if(c?.learnerRange)setRange('learner',...c.learnerRange);$('samePhrase').checked=!!c?.samePhrase;}};
}
